numberofways(n, m) {
  dp = new int[n+2][n+2];
  memset(dp, 0, sizeof(dp));
  dp[0][n+1] = 1;
  for (k = n; k >= m; k--) {
    for (i = 0; i <= n; i++) {
      dp[i][k] = dp[i][k+1];
      if (i - k >= 0) dp[i][k] = (dp[i][k] + dp[i-k][k]);
    }
  }
  return dp[n][m];
}

